using LocalHomeModule;
using System.Text;
using System.Text.Json;
static class EventChecks
{
 static MechanismDefinition Node(string id,string mode="once",float delay=0)=>new(id,id,"rotate",new(),null,Array.Empty<int>(),Array.Empty<MechanismPoint>(),Duration:1,Delay:delay,Mode:mode);
 static HomeRuntime Setup(string mode="once",float delay=0)
 {
  mod.TipMsgCore.i.mainplayer=null;
  var h=new HomeRuntime();h.UpsertMechanism(Node("B"));h.UpsertMechanism(Node("C") with{ParentId="B"});
  h.UpsertMechanism(Node("A",mode,delay) with{OnCompleteTargets=new[]{"B"},OnCycleTargets=new[]{"B"}});h.TickForTest();h.ClockForTest("A",1000);return h;
 }
 internal static void Run(Action<string,Action> test,Action<bool,string> check)
 {
  test("once delayed natural completion emits exactly once and starts subtree",()=>{var h=Setup(delay:2);h.EventsForTest(3999);check(!h.Starts.ContainsKey("B"),"early");h.EventsForTest(4000);check(h.Starts["B"]==4300&&h.Starts["C"]==4300,"boundary/subtree");h.EventsForTest(10000);check(h.Starts["B"]==4300,"repeat complete");});
  foreach(string mode in new[]{"loop","pingpong"}) test(mode+" full period delay and low-frame cycle suppression",()=>{var h=Setup(mode,2);long end=mode=="loop"?4000:5000;h.EventsForTest(end-1);check(!h.Starts.ContainsKey("B"),"half/early cycle");h.EventsForTest(end);check(h.Starts["B"]==end+300,"boundary");h.EventsForTest(103000);check(h.Starts["B"]==103300,"missed cycles");h.EventsForTest(103001);check(h.Starts["B"]==103300,"replayed backlog");});
  test("manual end freezes event emissions and reset clears progress",()=>{var h=Setup();h.EndMechanisms();h.EventsForTest(9000);check(!h.Starts.ContainsKey("B"),"manual end linked");h.ResetMechanisms();check(h.EventCountForTest==0,"reset cursor");h.ClockForTest("A",1000);h.EventsForTest(2000);check(h.Starts.ContainsKey("B"),"new epoch after reset");});
  test("explicit restart creates new epoch without clearing unrelated event source",()=>{var h=Setup();h.EventsForTest(2000);check(h.EventCountForTest==1,"target cleared source cursor");h.EventsForTest(2500);check(h.Starts["B"]==2300,"source re-fired");h.ClockForTest("A",1000);h.StartMechanisms("A");long restarted=h.Starts["A"];h.EventsForTest(restarted+1000);check(h.Starts["B"]==restarted+1300,"restart no completion");});
  test("normal and debug loops advance independent epochs and debug reset retains normal cursor",()=>{var h=Setup("loop");h.EventsForTest(2000);h.SetMechanismDebug(true);h.ClockForTest("A",1500);h.EventsForTest(2499);check(h.Starts["B"]==2300&&!h.DebugStarts.ContainsKey("B"),"debug epoch not independent");long revision=h.MechanismRevisionForTest;h.EventsForTest(2500);check(h.DebugStarts["B"]==2800&&h.Starts["B"]==2300,"debug leak");check(h.MechanismRevisionForTest==revision,"debug event marked network");h.EventsForTest(3000);check(h.Starts["B"]==3300&&h.DebugStarts["B"]==2800,"normal paused or altered debug");check(h.MechanismRevisionForTest>revision,"normal event failed to mark network in debug");h.ResetMechanisms();h.SetMechanismDebug(false);h.EventsForTest(3001);check(h.Starts["B"]==3300&&h.EventCountForTest==1,"normal cursor lost");});
  test("normal once completes during debug and both timelines keep distinct starts",()=>{var h=Setup();h.SetMechanismDebug(true);h.ClockForTest("A",1500);long revision=h.MechanismRevisionForTest;h.EventsForTest(2000);check(h.Starts["B"]==2300&&h.Starts["C"]==2300&&!h.DebugStarts.ContainsKey("B"),"normal once delayed until debug exit");check(h.MechanismRevisionForTest>revision,"normal once not scheduled for sync");revision=h.MechanismRevisionForTest;h.EventsForTest(2500);check(h.DebugStarts["B"]==2800&&h.Starts["B"]==2300,"debug completion changed normal epoch");check(h.MechanismRevisionForTest==revision,"debug completion scheduled sync");h.SetMechanismDebug(false);h.EventsForTest(2501);check(h.Starts["B"]==2300,"normal completion replayed at debug exit");});
  test("freezing either timeline does not freeze the other",()=>{var h=Setup();h.EndMechanisms();h.SetMechanismDebug(true);h.ClockForTest("A",1000);long revision=h.MechanismRevisionForTest;h.EventsForTest(2000);check(!h.Starts.ContainsKey("B")&&h.DebugStarts["B"]==2300,"normal freeze leaked into debug");check(h.MechanismRevisionForTest==revision,"debug emitted network mark");var r=Setup();r.SetMechanismDebug(true);r.ClockForTest("A",1000);r.EndMechanisms();revision=r.MechanismRevisionForTest;r.EventsForTest(2000);check(r.Starts["B"]==2300&&!r.DebugStarts.ContainsKey("B"),"debug freeze paused normal");check(r.MechanismRevisionForTest>revision,"normal event not marked while debug frozen");});
  test("event target subtrees reserved from global start",()=>{var h=Setup();h.ResetMechanisms();h.StartMechanisms();check(h.Starts.Keys.ToHashSet().SetEquals(new[]{"A"}),"global activated events");});
  test("snapshot prevents same tick event chain recursion even zero-length tracks",()=>{var h=new HomeRuntime();h.UpsertMechanism(Node("C"));h.UpsertMechanism(Node("B") with{Kind="track",Track=new[]{new MechanismPoint(),new MechanismPoint()},OnCompleteTargets=new[]{"C"}});h.UpsertMechanism(Node("A") with{OnCompleteTargets=new[]{"B"}});h.ClockForTest("A",1000);h.EventsForTest(5000);check(h.Starts["B"]==5300&&!h.Starts.ContainsKey("C"),"recursive apply");h.EventsForTest(5300);check(h.Starts["C"]==5600,"next tick chain");});
  test("mutual event graph is bounded to snapshot and unique target starts",()=>{var h=Setup("loop");h.ResetMechanisms();h.UpsertMechanism(Node("B","loop") with{OnCycleTargets=new[]{"A"}});h.ClockForTest("A",1000);h.ClockForTest("B",1000);h.EventsForTest(500000);check(h.Starts["A"]==500300&&h.Starts["B"]==500300,"mutual snapshot");h.EventsForTest(500301);check(h.Starts["A"]==500300,"recursive mutual chain");});
  test("delete cleans both event arrays and persisted references",()=>{var h=Setup();h.ResetMechanisms();h.DeleteMechanism("B");var a=h.Mechanisms.Single(n=>n.Id=="A");check(a.OnCompleteTargets!.Length==0&&a.OnCycleTargets!.Length==0,"dangling targets");var restored=new HomeRuntime{SavePath=h.SavePath};restored.LoadForTest();check(restored.Mechanisms.Length==2,"clean save failed");});
  test("upsert/load/getter deeply detach event target arrays",()=>{var h=Setup();h.ResetMechanisms();var targets=new[]{"B"};h.UpsertMechanism(h.Mechanisms.Single(n=>n.Id=="A") with{OnCompleteTargets=targets});targets[0]="BAD";var copy=h.Mechanisms;copy.Single(n=>n.Id=="A").OnCompleteTargets![0]="BAD";check(h.Mechanisms.Single(n=>n.Id=="A").OnCompleteTargets![0]=="B","alias");var r=new HomeRuntime{SavePath=h.SavePath};r.LoadForTest();check(r.Mechanisms.Single(n=>n.Id=="A").OnCycleTargets![0]=="B"&&r.Starts.Count==0&&r.EventCountForTest==0,"disk/cursor");});
  test("network carries validated events but remote never fires own starts",()=>{var h=Setup();var nodes=h.Mechanisms;var packet=new{Revision=1,Nodes=nodes,Items=h.Items,Starts=new Dictionary<string,long>{{"A",1000}},Frozen=0};string data=Convert.ToBase64String(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(packet)));h.ReceiveForTest("peer","LHM1:"+JsonSerializer.Serialize(new{Batch=Guid.NewGuid().ToString("N"),Index=0,Count=1,Data=data}));check(h.RemoteCount==1,"events rejected");h.RemoteForTest("peer");check(!h.Starts.ContainsKey("B"),"remote fired local");nodes.Single(n=>n.Id=="A").OnCompleteTargets![0]="MISSING";check(h.RemoteNodesForTest("peer").Single(n=>n.Id=="A").OnCompleteTargets![0]=="B","network alias");});
  test("preview draft events ignored while saved timeline continues",()=>{var h=Setup();h.ResetMechanisms();h.UpsertMechanism(Node("D"));h.ClockForTest("A",1000);var draft=h.Mechanisms.Single(n=>n.Id=="A") with{OnCompleteTargets=new[]{"D"}};h.SetRotationPreview(draft,1);h.EventsForTest(2000);check(h.Starts["B"]==2300&&h.Starts["C"]==2300&&!h.Starts.ContainsKey("D"),"saved timeline paused or draft fired");});
  test("network rejects missing self and duplicate event target definitions",()=>{foreach(var targets in new[]{new[]{"MISSING"},new[]{"A"},new[]{"B","B"}}){var h=Setup();var nodes=h.Mechanisms.Select(n=>n.Id=="A"?n with{OnCompleteTargets=targets}:n).ToArray();string data=Convert.ToBase64String(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(new{Revision=1,Nodes=nodes,Items=h.Items,Starts=new Dictionary<string,long>(),Frozen=0})));h.ReceiveForTest("bad","LHM1:"+JsonSerializer.Serialize(new{Batch=Guid.NewGuid().ToString("N"),Index=0,Count=1,Data=data}));check(h.RemoteCount==0,"bad network event accepted");}});
  test("zero duration once completes after delay but stationary loops have no cycle",()=>{foreach(string mode in new[]{"once","loop","pingpong"}){var h=Setup(mode,2);h.ResetMechanisms();h.UpsertMechanism(h.Mechanisms.Single(n=>n.Id=="A") with{Kind="track",Track=new[]{new MechanismPoint(),new MechanismPoint()}});h.ClockForTest("A",1000);h.EventsForTest(2999);check(!h.Starts.ContainsKey("B"),"stationary early");h.EventsForTest(3000);check(h.Starts.ContainsKey("B")== (mode=="once"),"stationary semantics");}});
  test("future start and event type are respected",()=>{var h=Setup();h.ResetMechanisms();h.UpsertMechanism(h.Mechanisms.Single(n=>n.Id=="A") with{OnCompleteTargets=null,OnCycleTargets=new[]{"B"}});h.ClockForTest("A",5000);h.EventsForTest(4999);h.EventsForTest(10000);check(!h.Starts.ContainsKey("B"),"once dispatched cycle event");h.ResetMechanisms();h.UpsertMechanism(h.Mechanisms.Single(n=>n.Id=="A") with{Mode="loop",OnCompleteTargets=new[]{"B"},OnCycleTargets=null});h.ClockForTest("A",1000);h.EventsForTest(10000);check(!h.Starts.ContainsKey("B"),"loop dispatched completion event");});
  test("baseline change clears event epochs",()=>{var h=Setup();h.EventsForTest(2000);h.Items=h.Items.Select(p=>p with{X=p.X+1}).ToArray();h.TickForTest();check(h.EventCountForTest==0&&h.Starts.Count==0,"baseline stale progress");});
 }
}
